CREATE TYPE "PublishStatus" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "EnquiryStatus" AS ENUM ('NEW','CONTACTED','IN_PROGRESS','CLOSED');
CREATE TYPE "SubmissionStatus" AS ENUM ('NEW','REVIEWED','ARCHIVED');
CREATE TABLE "AdminUser"("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AdminSession"("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "AdminUser"("id") ON DELETE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AdminSession_expiresAt_idx" ON "AdminSession"("expiresAt");
CREATE TABLE "SiteSetting"("key" TEXT PRIMARY KEY,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "HomepageSection"("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"eyebrow" TEXT,"body" TEXT,"content" JSONB NOT NULL DEFAULT '{}',"visible" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Service"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"overview" TEXT NOT NULL,"icon" TEXT NOT NULL DEFAULT 'Sparkles',"image" TEXT NOT NULL,"benefits" JSONB NOT NULL DEFAULT '[]',"deliverables" JSONB NOT NULL DEFAULT '[]',"process" JSONB NOT NULL DEFAULT '[]',"faqs" JSONB NOT NULL DEFAULT '[]',"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Service_status_sortOrder_idx" ON "Service"("status","sortOrder");
CREATE TABLE "Industry"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"overview" TEXT NOT NULL,"image" TEXT NOT NULL,"challenges" JSONB NOT NULL DEFAULT '[]',"solutions" JSONB NOT NULL DEFAULT '[]',"serviceSlugs" JSONB NOT NULL DEFAULT '[]',"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Industry_status_sortOrder_idx" ON "Industry"("status","sortOrder");
CREATE TABLE "ProjectCategory"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Project"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"clientLabel" TEXT,"description" TEXT NOT NULL,"overview" TEXT NOT NULL,"challenge" TEXT NOT NULL,"approach" TEXT NOT NULL,"deliverables" JSONB NOT NULL DEFAULT '[]',"gallery" JSONB NOT NULL DEFAULT '[]',"results" JSONB NOT NULL DEFAULT '[]',"image" TEXT NOT NULL,"demoContent" BOOLEAN NOT NULL DEFAULT true,"verifiedResults" BOOLEAN NOT NULL DEFAULT false,"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "_ProjectToProjectCategory"("A" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"B" TEXT NOT NULL REFERENCES "ProjectCategory"("id") ON DELETE CASCADE,PRIMARY KEY("A","B"));
CREATE INDEX "_ProjectToProjectCategory_B_index" ON "_ProjectToProjectCategory"("B");
CREATE INDEX "Project_status_sortOrder_idx" ON "Project"("status","sortOrder");
CREATE TABLE "Testimonial"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"role" TEXT NOT NULL,"company" TEXT NOT NULL,"quote" TEXT NOT NULL,"avatar" TEXT,"demoContent" BOOLEAN NOT NULL DEFAULT true,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Testimonial_status_sortOrder_idx" ON "Testimonial"("status","sortOrder");
CREATE TABLE "ProcessStep"("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"visible" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "ProcessStep_visible_sortOrder_idx" ON "ProcessStep"("visible","sortOrder");
CREATE TABLE "ArticleCategory"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL UNIQUE);
CREATE TABLE "Article"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"excerpt" TEXT NOT NULL,"body" TEXT NOT NULL,"image" TEXT NOT NULL,"categoryId" TEXT NOT NULL REFERENCES "ArticleCategory"("id"),"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Article_status_publishedAt_idx" ON "Article"("status","publishedAt");
CREATE INDEX "Article_categoryId_idx" ON "Article"("categoryId");
CREATE TABLE "JobOpening"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"team" TEXT NOT NULL,"location" TEXT NOT NULL,"employmentType" TEXT NOT NULL,"summary" TEXT NOT NULL,"description" TEXT NOT NULL,"requirements" JSONB NOT NULL DEFAULT '[]',"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "JobOpening_status_sortOrder_idx" ON "JobOpening"("status","sortOrder");
CREATE TABLE "Enquiry"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"company" TEXT,"service" TEXT,"message" TEXT NOT NULL,"source" TEXT NOT NULL DEFAULT 'contact',"status" "EnquiryStatus" NOT NULL DEFAULT 'NEW',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Enquiry_status_createdAt_idx" ON "Enquiry"("status","createdAt");
CREATE INDEX "Enquiry_email_idx" ON "Enquiry"("email");
CREATE TABLE "StrategyCallRequest"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"company" TEXT,"service" TEXT,"preferredAt" TIMESTAMP(3) NOT NULL,"timezone" TEXT NOT NULL,"message" TEXT,"status" "SubmissionStatus" NOT NULL DEFAULT 'NEW',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "StrategyCallRequest_status_createdAt_idx" ON "StrategyCallRequest"("status","createdAt");
CREATE TABLE "JobApplication"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"position" TEXT NOT NULL,"jobId" TEXT REFERENCES "JobOpening"("id") ON DELETE SET NULL,"resumeUrl" TEXT NOT NULL,"resumeFilename" TEXT,"resumeContentType" TEXT,"resumeData" BYTEA,"portfolioUrl" TEXT,"message" TEXT NOT NULL,"status" "SubmissionStatus" NOT NULL DEFAULT 'NEW',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "JobApplication_status_createdAt_idx" ON "JobApplication"("status","createdAt");
CREATE TABLE "MediaAsset"("id" TEXT PRIMARY KEY,"filename" TEXT NOT NULL,"url" TEXT NOT NULL,"contentType" TEXT NOT NULL,"size" INTEGER NOT NULL,"isPrivate" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MediaAsset_isPrivate_createdAt_idx" ON "MediaAsset"("isPrivate","createdAt");
CREATE TABLE "LegalPage"("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"seoTitle" TEXT,"seoDescription" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'PUBLISHED',"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RateLimit"("key" TEXT PRIMARY KEY,"count" INTEGER NOT NULL DEFAULT 0,"resetAt" TIMESTAMP(3) NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "RateLimit_resetAt_idx" ON "RateLimit"("resetAt");
